using GSPTaskMiningAnalyzer.Models;
namespace GSPTaskMiningAnalyzer;
public interface IInsightProvider{IReadOnlyList<AutomationOpportunity> GetInsights(AnalysisResult result);} public sealed class RuleBasedInsightProvider: IInsightProvider{public IReadOnlyList<AutomationOpportunity> GetInsights(AnalysisResult r)=>new AutomationOpportunityService().Find(r);} 
public sealed class AutomationOpportunityService{ public List<AutomationOpportunity> Find(AnalysisResult r){var list=new List<AutomationOpportunity>(); foreach(var c in r.Chains2.Concat(r.Chains3).GroupBy(x=>x.Key).Select(g=>new{Key=g.Key,Count=g.Sum(x=>x.Value)}).OrderByDescending(x=>x.Count).Take(20)){var apps=c.Key.Split('→',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries).Distinct(StringComparer.OrdinalIgnoreCase).ToArray(); if(apps.Length<2) continue; var total=r.Sessions.Where(s=>apps.Contains(s.ProcessName,StringComparer.OrdinalIgnoreCase)).Sum(s=>s.DurationSeconds); var avg=c.Count>0?total/c.Count:0; var days=Math.Max(1,(r.To-r.From)?.TotalDays??1); var freq=c.Count/days; var stability=Math.Min(1.0,c.Count/Math.Max(1.0,r.Sessions.Count)); var systems=Math.Min(100,apps.Length*20); var score=(int)Math.Clamp(freq*10 + Math.Min(25,avg/60*5)+stability*25+systems,0,100); var cat=score>=80?"высокий потенциал":score>=60?"средний потенциал":score>=40?"требуется изучение":"низкий потенциал"; var sol=apps.Length>=2?"Интеграция/API":"Скрипт"; list.Add(new(c.Key,string.Join(", ",apps),freq,avg,total,r.Sessions.Select(s=>s.UserName).Distinct().Count(),r.Sessions.Select(s=>s.MachineName).Distinct().Count(),stability,0,total*.2,Math.Min(100,score+10),score,cat,sol,$"Повторяющаяся цепочка встречается {c.Count} раз; рекомендация является гипотезой и требует проверки аналитиком."));} return list;} }
